namespace ghidra.app.plugin.core.debug.gui.control;



using docking;
using docking.action;
using docking.action;
using ghidra.app.services;
using ghidra.debug.api.target;
using ghidra.debug.api.target;
using ghidra.debug.api.target.Target;
using ghidra.debug.api.target.Target;
using ghidra.framework.plugintool;

class TargetDockingAction : DockingAction {
	private PluginTool tool;
	private ActionName action;
	private string defaultDescription;

	private ActionEntry entry;

	public TargetDockingAction(string name, string owner, KeyBindingType keyBindingType,
			PluginTool tool, ActionName action, string defaultDescription) : base(name, owner, keyBindingType)
    {
		this.tool = tool;
		this.action = action;
		this.defaultDescription = defaultDescription;
	}

	private ActionEntry findEntry(ActionContext context) {
		DebuggerTraceManagerService traceManager =
			tool.getService(typeof(DebuggerTraceManagerService));
		if (traceManager == null) {
			return null;
		}
		Target target = traceManager.getCurrent().getTarget();
		if (target == null) {
			return null;
		}
		return target.collectActions(action, context, ObjectArgumentPolicy.CURRENT_AND_RELATED)
				.values()
				.stream()
				.filter(e => !e.requiresPrompt())
				.sorted(Comparator.comparing(e => -e.specificity()))
				.findFirst()
				.orElse(null);
		// TODO: What if multiple match? Do I care to display the extras?
		// Esp., step process vs step thread
	}

	protected void updateFromContext(ActionContext context) {
		entry = findEntry(context);
		if (entry == null) {
			getToolBarData().setIcon(action.icon());
			setDescription(defaultDescription);
		}
		else {
			getToolBarData().setIcon(entry.icon());
			setDescription(entry.details());
		}
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		updateFromContext(context);
		return entry != null && entry.isEnabled();
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (entry == null) {
			return;
		}
		TargetActionTask.runAction(tool, getName(), entry);
	}
}
